contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try calling mintSynth as if msg.sender is a curated pool. Since the checker deploys a fresh C,
    // we simply call mintSynth directly from this contract; the call will succeed only if this contract
    // is considered a curated pool by the DAO used by C. The property accounts for both success and revert.
    function run(address poolCaller, address member, uint amount) public payable {
        require(member != address(0), "member!=0");
        // Read pre-state
        uint beforeBalance = c.balanceOf(member);
        uint beforeDebt = c.getmapAddress_LPDebt(poolCaller);

        bool reverted;
        // Call mintSynth on c, but it is restricted by onlyPool modifier which checks POOLFACTORY.isCuratedPool(msg.sender).
        // We attempt the call and capture whether it reverted.
        try c.mintSynth{value:0}(member, amount) returns (uint syntheticAmount) {
            reverted = false;
            // syntheticAmount is return value; ignore here as we can observe effects via public getters
        } catch {
            reverted = true;
        }

        uint afterBalance = c.balanceOf(member);
        uint afterDebt = c.getmapAddress_LPDebt(poolCaller);

        // If the call did not revert, then exactly 'amount' tokens must have been minted to member
        // (i.e., balance increased by amount) AND the pool's LP debt increased by amount.
        // If it reverted, we cannot assume any state change; assert allows either reverted==true OR the relation holds.
        assert(reverted || (afterBalance >= beforeBalance && afterDebt >= beforeDebt && afterBalance - beforeBalance == amount && afterDebt - beforeDebt == amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We try to call mintSynth on C where this contract acts as msg.sender (a pool).
    // The property: either the call reverts, or balance(member) and mapSynth_LPDebt[msg.sender]
    // both increase by exactly `amount`.
    function run(address member, uint amount) public payable {
        require(member != address(0), "member!=0");

        // Observe pre-state
        uint beforeBalance = c.balanceOf(member);
        uint beforeDebt = c.getmapAddress_LPDebt(address(this));

        bool reverted = false;
        uint returned;
        // Call mintSynth as this contract (msg.sender == this) — onlyPool may revert.
        try c.mintSynth(member, amount) returns (uint syntheticAmount) {
            reverted = false;
            returned = syntheticAmount;
        } catch {
            reverted = true;
            returned = 0;
        }

        // Observe post-state
        uint afterBalance = c.balanceOf(member);
        uint afterDebt = c.getmapAddress_LPDebt(address(this));

        // If not reverted then exactly `amount` tokens were minted to member and debt increased by amount.
        // Note: allow that balances/debts could only increase (use >=) and equality of increments to amount.
        assert(reverted || (afterBalance >= beforeBalance && afterDebt >= beforeDebt && afterBalance - beforeBalance == amount && afterDebt - beforeDebt == amount));
    }

    receive() external payable {}
}

