contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: pool address (must be a curated pool according to DAO), member to receive synth, amount of LP tokens to transfer in to C before mint, and amountRequested to mint
    function run(address pool, address member, uint lpTransferIn, uint amountRequested) public payable {
        require(pool != address(0) && member != address(0));

        // Read initial observable state
        uint beforeTotal = c.totalSupply();
        uint beforeMember = c.balanceOf(member);
        uint beforePoolLPBalance = c.getmapAddress_LPBalance(pool);
        uint beforePoolLPDebt = c.getmapAddress_LPDebt(pool);
        uint poolTokenBalanceBefore = iBEP20(pool).balanceOf(address(c));

        // If caller (this contract) should transfer LP tokens into c to simulate pool providing LPs,
        // we attempt to transferFrom; this will only succeed if allowance/balance are set externally in the environment.
        // It's acceptable if the transfer fails (reverts) — we catch mintSynth revert.
        bool reverted;
        try c.mintSynth(member, amountRequested) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state regardless of revert (calls to view funcs only)
        uint afterTotal = c.totalSupply();
        uint afterMember = c.balanceOf(member);
        uint afterPoolLPBalance = c.getmapAddress_LPBalance(pool);
        uint afterPoolLPDebt = c.getmapAddress_LPDebt(pool);
        uint poolTokenBalanceAfter = iBEP20(pool).balanceOf(address(c));

        // General rule to assert:
        // If mintSynth call did not revert, then:
        //  - totalSupply increased by exactly the minted amount (afterTotal - beforeTotal == amountRequested)
        //  - the member's balance increased by exactly amountRequested
        //  - pool LP debt increased by exactly amountRequested
        //  - pool LP balance did not decrease (it should increase by reported added LP units >= 0)
        //  - the observed token balance of the pool contract at C did not decrease (non-negative change)
        // If it reverted, no observable balances on C (totalSupply and member balance) changed.

        assert(
            reverted
            ? (afterTotal == beforeTotal && afterMember == beforeMember && afterPoolLPBalance == beforePoolLPBalance && afterPoolLPDebt == beforePoolLPDebt && poolTokenBalanceAfter == poolTokenBalanceBefore)
            : (
                afterTotal == beforeTotal + amountRequested
                && afterMember == beforeMember + amountRequested
                && afterPoolLPDebt == beforePoolLPDebt + amountRequested
                && afterPoolLPBalance >= beforePoolLPBalance
                && poolTokenBalanceAfter >= poolTokenBalanceBefore
            )
        );
    }

    // Minimal interface to call balanceOf on pool LP token
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test behaviour of burnSynth as invoked by a pool (msg.sender must be a curated pool).
    // Parameters:
    // - pool: the pool address that will call burnSynth on C (must be non-zero)
    function run(address pool) public payable {
        require(pool != address(0));

        // Observe before-state via public getters
        uint beforeTotal = c.totalSupply();
        uint beforePoolDebt = c.getmapAddress_LPDebt(pool);
        uint beforePoolLPBalance = c.getmapAddress_LPBalance(pool);
        uint beforePoolTokenBalance = iBEP20(pool).balanceOf(address(c));

        // We must perform the state-changing call as a top-level statement. Since burnSynth uses msg.sender to index
        // its maps and expects the caller to be a curated pool, we call it directly on c; the checker will set up
        // the environment so that msg.sender (this contract) is allowed — but the contract under test expects the
        // pool itself to call. To simulate that, we use the pool address as a param to the test and require that
        // the pool contract invokes burnSynth by making this contract the msg.sender. However, per harness rules,
        // the test's deployment makes msg.sender the InvMutTest contract for calls on c, so we instead perform
        // a direct top-level call and record whether it reverted.
        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint afterTotal = c.totalSupply();
        uint afterPoolDebt = c.getmapAddress_LPDebt(pool);
        uint afterPoolLPBalance = c.getmapAddress_LPBalance(pool);
        uint afterPoolTokenBalance = iBEP20(pool).balanceOf(address(c));

        // General invariant to assert:
        // - If burnSynth reverted: no observable decreases in totalSupply or pool debt/LP balance/token balance are required,
        //   but we assert that at least one of the main observed values did not decrease (to ensure the call was reachable)
        // - If burnSynth did not revert: totalSupply decreased by exactly the synthetic amount burned (equal to before - after),
        //   pool LP debt decreased by the same amount, and pool LP balance did not increase (it may decrease or stay same),
        //   and the external token balance of pool held by C did not increase.

        // Because we cannot read the internal burned amount directly, we express equality between decreases of totalSupply and pool debt.
        assert(
            reverted
            ? (
                // When reverted, require that either nothing changed (common) OR at least no unexpected increase in debts/balances occurred
                afterTotal <= beforeTotal && afterPoolDebt <= beforePoolDebt && afterPoolLPBalance <= beforePoolLPBalance && afterPoolTokenBalance <= beforePoolTokenBalance
              )
            : (
                // Not reverted: decreases in totalSupply and pool debt must be equal, and pool LP balance and token balance must not increase
                (beforeTotal >= afterTotal) && (beforePoolDebt >= afterPoolDebt) && (beforeTotal - afterTotal == beforePoolDebt - afterPoolDebt)
                && afterPoolLPBalance <= beforePoolLPBalance
                && afterPoolTokenBalance <= beforePoolTokenBalance
              )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: pool calling mintSynth(member, amount)
    // Params:
    // - pool: address of the pool (must be non-zero)
    // - member: recipient of minted synth
    // - amount: requested synthetic amount to mint
    function run(address pool, address member, uint amount) public payable {
        require(pool != address(0));
        require(member != address(0));

        // Observe before-values via public getters
        uint beforeTotal = c.totalSupply();
        uint beforeMemberBal = c.balanceOf(member);
        uint beforePoolDebt = c.getmapAddress_LPDebt(pool);

        // Call under test as a top-level statement; capture revert
        bool reverted;
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint afterTotal = c.totalSupply();
        uint afterMemberBal = c.balanceOf(member);
        uint afterPoolDebt = c.getmapAddress_LPDebt(pool);

        // Assert general rule:
        // If the call reverted, nothing further required. If it did not revert, then totalSupply increased
        // by exactly the member balance increase, and the pool's recorded debt did not decrease and increased by at
        // most the supply increase (i.e. pool debt increase >= 0 and <= supply increase). This encodes that minted
        // synth went to member and pool debt was recorded.
        assert(
            reverted
            || (
                afterTotal >= beforeTotal
                && afterMemberBal >= beforeMemberBal
                && (afterTotal - beforeTotal) == (afterMemberBal - beforeMemberBal)
                && afterPoolDebt >= beforePoolDebt
                && (afterPoolDebt - beforePoolDebt) <= (afterTotal - beforeTotal)
            )
        );
    }

    receive() external payable {}
}

