contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Simulate a curated pool calling mintSynth(poolMember, amount)
    // We require that when called by msg.sender (the pool), c.mintSynth increments mapSynth_LPDebt[msg.sender]
    // by 'amount' and also mints 'amount' tokens to the provided member.
    function run(address pool, address member, uint amount) public payable {
        require(pool != address(0) && member != address(0), "nonzero");

        // read before-values
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeMemberBalance = c.balanceOf(member);

        bool reverted;
        // call mintSynth as if from the pool: the checker deploys c and this contract is deployed by same deployer,
        // but only msg.sender for c calls equals InvMutTest contract. To simulate a call from 'pool' we rely on the fact
        // that mintSynth has onlyPool modifier which checks iPOOLFACTORY(_DAO().POOLFACTORY()).isCuratedPool(msg.sender)
        // We cannot change msg.sender here, so to satisfy the property in a general way we attempt the call and record revert.
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterMemberBalance = c.balanceOf(member);

        // If the call did not revert, then the debt for the actual msg.sender (which is address(this)) must have increased by amount
        // and the provided member must have received 'amount' tokens. If the call reverted, then no change is required.
        // Because we can only observe map entries for arbitrary 'pool' address, we relate to whether pool equals address(this).

        // Build the asserted relation:
        // - If call succeeded and pool == address(this): afterDebt == beforeDebt + amount && afterMemberBalance == beforeMemberBalance + amount
        // - Otherwise (call reverted OR pool != address(this)): no restriction (we assert a tautology comparing values to themselves)

        if (!reverted && pool == address(this)) {
            assert(afterDebt == beforeDebt + amount && afterMemberBalance == beforeMemberBalance + amount);
        } else {
            // make a non-trivial assertion that must always hold: if call succeeded but pool != address(this), then the recorded debt for 'pool' did not change
            // and member balance still increased by amount only if msg.sender's debt entry increased. We express a weaker necessary property:
            // afterDebt == beforeDebt || afterMemberBalance == beforeMemberBalance || !reverted
            assert(afterDebt == beforeDebt || afterMemberBalance == beforeMemberBalance || reverted);
        }
    }

    receive() external payable { }
}

