contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We simulate a curated pool calling mintSynth on C. The test takes as inputs
    // the pool address (must be treated as an externally-owned account in this context)
    // and an amount to mint. We require nothing about the pool being actually curated
    // in the environment; the test observes behavior only when the call succeeds.
    function run(address pool, uint amount) public payable {
        require(pool != address(0), "pool nonzero");

        // Read pre-state from C
        uint preTotal = c.totalSupply();
        uint preDebt = c.getmapAddress_LPDebt(pool);
        uint preLPBal = c.getmapAddress_LPBalance(pool);

        // Attempt to call mintSynth as if from the pool. Because the harness will
        // execute run with msg.sender == this contract, we must invoke the pool's
        // action by asking the pool-address to call c.mintSynth in the real system.
        // However, we are constrained to call c only through its public interface.
        // To respect the constraint that every state-changing call on c must be a
        // top-level statement, we perform the call directly. We record whether it reverted.
        bool reverted;
        try c.mintSynth(address(this), amount) {
            // If this contract is not recognized as a curated pool, the call will revert
            // due to onlyPool modifier or other checks. We treat both outcomes.
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state from C
        uint postTotal = c.totalSupply();
        uint postDebt = c.getmapAddress_LPDebt(pool);
        uint postLPBal = c.getmapAddress_LPBalance(pool);

        // General property to hold for all inputs: if the call did NOT revert, then
        // totalSupply increased by exactly 'amount', and mapSynth_LPDebt for the pool
        // increased by amount, and mapSynth_LPBalance for the pool did not decrease.
