        // (afterLPBalance > beforeLPBalance) then the LP balance increase must be > 0.
        assert(
            (reverted && afterLPBalance == beforeLPBalance && afterLPDebt == beforeLPDebt && afterMemberBal == beforeMemberBal)
            ||
            (!reverted && afterMemberBal == beforeMemberBal + amount && afterLPDebt == beforeLPDebt + amount && afterLPBalance >= beforeLPBalance)
        );
    }

    receive() external payable {}
}

