contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check. The function takes
    // pool (the caller pool address) and member as parameters and an amount
    // to mint; it attempts to simulate a Pool calling c.mintSynth by
    // invoking mintSynth from this contract (the checker deploys c and then
    // calls run with this contract as msg.sender for calls into c). Because
    // mintSynth has the onlyPool modifier that checks iPOOLFACTORY(...).isCuratedPool(msg.sender),
    // the call may revert; the property asserts relationships when the call
    // succeeds and also that when it reverts there was no change to observed state.
    function run(address pool, address member, uint amount) public payable {
        require(true);

        // Read pre-state from c using only its public surface
        uint pre_total = c.totalSupply();
        uint pre_debt = c.getmapAddress_LPDebt(pool);

        bool reverted = false;
        // Try to call mintSynth as msg.sender == this contract
        try c.mintSynth(member, amount) returns (uint syntheticAmount) {
            // call succeeded; syntheticAmount is returned value
            // Read post-state
            uint post_total = c.totalSupply();
            uint post_debt = c.getmapAddress_LPDebt(pool);

            // Assert that totalSupply increased by syntheticAmount and debt increased by syntheticAmount
            // (use single assert at end: store condition in local and assert it)
            bool ok = (post_total == pre_total + syntheticAmount) && (post_debt == pre_debt + syntheticAmount) && (syntheticAmount == amount || syntheticAmount == c.balanceOf(member));
            // The extra syntheticAmount==amount||... is to relate returned value to inputs or visible balances
            assert(ok);
            return;
        } catch {
            reverted = true;
        }

        // If reverted, ensure observable state did not increase the pre-values
        uint post_total2 = c.totalSupply();
        uint post_debt2 = c.getmapAddress_LPDebt(pool);

        // When reverted, expect no increase in totalSupply or debt (they must be <= pre values)
        assert(reverted == true && post_total2 == pre_total && post_debt2 == pre_debt);
    }

    receive() external payable { }
}

