contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a pool address and an arbitrary mint amount. The pool must be a curated pool
    // according to DAO; but we cannot query DAO preconditions here, so we conservatively
    // require the pool address is not zero. The test will call mintSynth on C as if from
    // the pool by using a low-level call (since msg.sender for c must be this contract when
    // invoking c methods). To simulate the pool calling mintSynth, we use c.mintSynth from
    // this test (which will enforce onlyPool modifier inside C). To satisfy onlyPool the
    // deployed c in the harness must consider this contract a curated pool; the checker will
    // set up environment accordingly for some inputs. We record before-values, then attempt
    // the call and observe whether it reverted. The assertion states that if the call did
    // not revert, then totalSupply increases by the returned amount and c's recorded debt
    // and LP balance for that pool are increased (i.e., new >= old), and if minted > 0 then
    // at least one of the recorded increases is > 0.

    function run(address pool, address member, uint amount) public payable {
        require(pool != address(0) && member != address(0));

        // read before-values
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeLPBal = c.getmapAddress_LPBalance(pool);

        bool reverted = false;
        uint returned = 0;
        // call mintSynth; this is a state-changing call and must be a top-level statement
        // Use try/catch invocation via external call to capture revert without nesting the call.
        // But per constraints, state-changing calls must be top-level statements; a try/catch
        // with external call still counts as top-level. We'll invoke via low-level call to
        // capture success and returned data.
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("mintSynth(address,address)", member, amount));
        if(!ok){ reverted = true; }
        else {
            // decode returned uint from mintSynth on success
            if(ret.length >= 32) {
                returned = abi.decode(ret, (uint));
            }
        }

        // read after-values
        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterLPBal = c.getmapAddress_LPBalance(pool);

        // General rule (single assert): If the call succeeded (not reverted)
        // 1) totalSupply increased by exactly the returned minted amount,
        // 2) recorded debt and LPBalance did not decrease (are >= before), and
        // 3) if returned > 0 then at least one of (afterDebt>beforeDebt) or (afterLPBal>beforeLPBal)
        // Note: this ties observable storage updates to the successful mint operation.
        assert(
            reverted || (
                // total supply increased by minted amount
                afterTotal == beforeTotal + returned
                // debt and lp balance are non-decreasing
                && afterDebt >= beforeDebt
                && afterLPBal >= beforeLPBal
                // if minted positive then some recorded increase happened
                && (returned == 0 || (afterDebt > beforeDebt || afterLPBal > beforeLPBal))
            )
        );
    }

    receive() external payable { }
}

