        assert(
            reverted
            ? (afterMemberBal == beforeMemberBal && afterDebt == beforeDebt && afterLPBal == beforeLPBal)
            : (memberInc == amount && debtInc == amount && afterLPBal >= beforeLPBal)
        );
    }

    receive() external payable {}
}

