contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run called by checker with arbitrary params. amountLP is LP units that the pool will transfer into C
    // minted is the synthetic amount pool requests to mint for member
    // pool is the address that will be treated as msg.sender by C (a curated pool). The checker deploys C freshly
    function run(address pool, address member, uint256 minted, uint256 amountLP) public payable {
        require(pool != address(0) && member != address(0));

        // Observe pre-state
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalMember = c.balanceOf(member);
        uint256 beforeDebt = c.getmapAddress_LPDebt(pool);
        uint256 beforeLPBal = c.getmapAddress_LPBalance(pool);

        // We need to simulate a call from pool. The testing harness will have this contract as deployer of c,
        // but cannot change msg.sender for external calls. However, C.mintSynth requires onlyPool modifier which
        // checks iPOOLFACTORY(_DAO().POOLFACTORY()).isCuratedPool(msg.sender) == true. We cannot satisfy that here.
        // To respect constraints (only call c as this contract), we instead perform a low-level call using the pool
        // address as the CALLER by invoking C via an external call forwarding: make pool invoke c.mintSynth in a
        // way that the pool is msg.sender. For that we rely on the pool address being a contract under checker control.
        // The test harness will still check the general invariant for traces where the call succeeds. We'll attempt the call
        // and record whether it reverted.

        // Prepare calldata for mintSynth(address member, uint amount)
        bytes memory data = abi.encodeWithSignature("mintSynth(address,uint256)", member, minted);
        bool reverted;
        // Try to invoke c.mintSynth from 'pool' by calling pool to delegatecall c; if pool is not a contract that performs that,
        // the call may revert — we capture revert flag.
        (bool ok, ) = pool.call(abi.encodeWithSignature("forward(address,bytes)", address(c), data));
        // Some pool contracts may not implement forward; if so, fallback to directly calling c with this contract as msg.sender,
        // marking it as reverted for our intended pool-call semantics.
        if(!ok){
            reverted = true;
        } else {
            // If pool.forward succeeded, we assume pool executed c.mintSynth; treat as not reverted
            reverted = false;
        }

        // Observe post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalMember = c.balanceOf(member);
        uint256 afterDebt = c.getmapAddress_LPDebt(pool);
        uint256 afterLPBal = c.getmapAddress_LPBalance(pool);

        // The invariant: if the attempted pool-call did not revert, then totalSupply and member balance increased by minted
        // and mapSynth_LPDebt increased by minted; otherwise no assumptions (we only assert implication).
        assert(reverted || (afterTotal == beforeTotal + minted && afterBalMember == beforeBalMember + minted && afterDebt == beforeDebt + minted));
    }

    // Fallback to accept any ether if needed by forwarded calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We require nonzero addresses to avoid trivial failures.
    // pool must be a contract that the checker can arrange to be a curated pool so the call may succeed.
    function run(address pool, address member, uint256 minted) public payable {
        require(pool != address(0) && member != address(0));

        // Observe pre-state via public view functions
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalMember = c.balanceOf(member);
        uint256 beforeDebt = c.getmapAddress_LPDebt(pool);

        // Attempt to have the pool call c.mintSynth(member, minted).
        // The only allowed top-level state-changing call on c is direct; so we call c.mintSynth here as this contract.
        // If the call reverts (e.g., because msg.sender is not a curated pool), we catch that and set reverted = true.
        bool reverted;
        try c.mintSynth(member, minted) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalMember = c.balanceOf(member);
        uint256 afterDebt = c.getmapAddress_LPDebt(pool);

        // General property: If the call did NOT revert then totalSupply and member balance increased by minted,
        // and the recorded LP debt for the pool increased by minted. If the call reverted we make no claim.
        assert(reverted || (afterTotal == beforeTotal + minted && afterBalMember == beforeBalMember + minted && afterDebt == beforeDebt + minted));
    }

    receive() external payable {}
}
